bool FTownPriceTable::LinkColumnAxis(const FTownPriceColumnTable& Columns)
{
    TMap<int32, int32> At;
    TArray<int32> Keys;

    At.Reserve(Columns.Records().Num());
    Keys.SetNum(Columns.Records().Num());

    for (const FTownPriceColumnRow& Column : Columns.Records())
    {
        const int32 Position = static_cast<int32>(Column.At);

        At.Add(Column.Goods, Position);
        Keys[Position] = Column.Goods;
    }

    for (const FTownPriceRow& Record : RecordsStorage)
    {
        if (Record.Price.Num() != Keys.Num())
        {
            UE_LOG(LogTemp, Error,
                TEXT("Tabbit: table `TownPrice` holds %d cells for one row and its column axis `TownPriceColumn` holds %d keys. The two files are from different builds."),
                Record.Price.Num(), Keys.Num());

            return false;
        }
    }

    ColumnAt = MoveTemp(At);
    ColumnKeys = MoveTemp(Keys);
    bColumnAxisLinked = true;

    return true;
}

TArray<int32> FTownPriceTable::RowKeys() const
{
    TArray<int32> Keys;
    Keys.Reserve(RecordsStorage.Num());

    for (const FTownPriceRow& Record : RecordsStorage)
    {
        Keys.Add(Record.Town);
    }

    return Keys;
}

const TArray<int32>* FTownPriceTable::Row(int32 Town) const
{
    const FTownPriceRow* Record = FindByTown(Town);
    return Record == nullptr ? nullptr : &Record->Price;
}

bool FTownPriceTable::At(int32 Town, int32 Goods, int32& OutCell) const
{
    const FTownPriceRow* Record = nullptr;
    int32 Position = 0;

    if (!CellAt(Town, Goods, Record, Position))
    {
        return false;
    }

    OutCell = Record->Price[Position];

    return true;
}


bool FTownPriceTable::HasAt(int32 Town, int32 Goods, bool& OutHasValue) const
{
    const FTownPriceRow* Record = nullptr;
    int32 Position = 0;

    if (!CellAt(Town, Goods, Record, Position))
    {
        return false;
    }

    OutHasValue = Record->bHasPriceAt[Position];

    return true;
}


bool FTownPriceTable::CellAt(int32 Town, int32 Goods, const FTownPriceRow*& OutRecord, int32& OutPosition) const
{
    if (!bColumnAxisLinked)
    {
        return false;
    }

    const FTownPriceRow* Record = FindByTown(Town);

    if (Record == nullptr)
    {
        return false;
    }

    const int32* Position = ColumnAt.Find(Goods);

    if (Position == nullptr)
    {
        return false;
    }

    OutRecord = Record;
    OutPosition = *Position;

    return true;
}



