FGoodsRow UMatrixDataLibrary::GetGoodsRow(int32 Key, bool& bFound)
{
    const FGoodsRow* Found = FMatrixData::Goods().FindById(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FGoodsRow();
}

int32 UMatrixDataLibrary::GetGoodsRowCount()
{
    return FMatrixData::Goods().Records().Num();
}

FGoodsRow UMatrixDataLibrary::GetGoodsRowAt(int32 Position, bool& bFound)
{
    const TArray<FGoodsRow>& Rows = FMatrixData::Goods().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FGoodsRow();
}


