bool UMatrixDataLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FMatrixData::ReadAll(BasePath, FileExtension);
}

bool FMatrixData::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FGoodsTable LoadedGoods;

    if (!LoadedGoods.Read(FPaths::Combine(BasePath, TEXT("Goods") + FileExtension)))
    {
        return false;
    }
    FTownPriceTable LoadedTownPrice;

    if (!LoadedTownPrice.Read(FPaths::Combine(BasePath, TEXT("TownPrice") + FileExtension)))
    {
        return false;
    }
    FTownPriceColumnTable LoadedTownPriceColumn;

    if (!LoadedTownPriceColumn.Read(FPaths::Combine(BasePath, TEXT("TownPriceColumn") + FileExtension)))
    {
        return false;
    }
    FElementChartTable LoadedElementChart;

    if (!LoadedElementChart.Read(FPaths::Combine(BasePath, TEXT("ElementChart") + FileExtension)))
    {
        return false;
    }
    FElementChartColumnTable LoadedElementChartColumn;

    if (!LoadedElementChartColumn.Read(FPaths::Combine(BasePath, TEXT("ElementChartColumn") + FileExtension)))
    {
        return false;
    }

    if (!LoadedTownPrice.LinkColumnAxis(LoadedTownPriceColumn))
    {
        return false;
    }
    if (!LoadedElementChart.LinkColumnAxis(LoadedElementChartColumn))
    {
        return false;
    }
    GoodsStorage = MoveTemp(LoadedGoods);
    TownPriceStorage = MoveTemp(LoadedTownPrice);
    TownPriceColumnStorage = MoveTemp(LoadedTownPriceColumn);
    ElementChartStorage = MoveTemp(LoadedElementChart);
    ElementChartColumnStorage = MoveTemp(LoadedElementChartColumn);

    return true;
}
